class Solution {
    public boolean isInterleave(String s1, String s2, String s3) {
        if (s1.length() + s2.length() != s3.length()) return false;
        return dfs(s1, s2, s3, 0, 0);
    }

    private boolean dfs(String s1, String s2, String s3, int i, int j) {
        int m = s1.length();
        int n = s2.length();
        if (i == m && j == n) return true;

        int k = i + j;
        boolean ok = false;
        if (i < m && s1.charAt(i) == s3.charAt(k)) ok = dfs(s1, s2, s3, i + 1, j);
        if (!ok && j < n && s2.charAt(j) == s3.charAt(k)) ok = dfs(s1, s2, s3, i, j + 1);
        return ok;
    }
}

class Solution {
    public boolean isInterleave(String s1, String s2, String s3) {
        int m = s1.length();
        int n = s2.length();
        if (m + n != s3.length()) return false;
        Boolean[][] memo = new Boolean[m + 1][n + 1];
        return dfs(s1, s2, s3, 0, 0, memo);
    }

    private boolean dfs(String s1, String s2, String s3, int i, int j, Boolean[][] memo) {
        int m = s1.length();
        int n = s2.length();
        if (i == m && j == n) return true;
        if (memo[i][j] != null) return memo[i][j];

        int k = i + j;
        boolean ok = false;
        if (i < m && s1.charAt(i) == s3.charAt(k)) ok = dfs(s1, s2, s3, i + 1, j, memo);
        if (!ok && j < n && s2.charAt(j) == s3.charAt(k)) ok = dfs(s1, s2, s3, i, j + 1, memo);

        memo[i][j] = ok;
        return ok;
    }
}

class Solution {
    public boolean isInterleave(String s1, String s2, String s3) {
        int m = s1.length();
        int n = s2.length();
        if (m + n != s3.length()) return false;

        boolean[] dp = new boolean[n + 1];
        dp[0] = true;
        for (int j = 1; j <= n; j++) {
            dp[j] = dp[j - 1] && s2.charAt(j - 1) == s3.charAt(j - 1);
        }

        for (int i = 1; i <= m; i++) {
            dp[0] = dp[0] && s1.charAt(i - 1) == s3.charAt(i - 1);
            for (int j = 1; j <= n; j++) {
                boolean fromS1 = dp[j] && s1.charAt(i - 1) == s3.charAt(i + j - 1);
                boolean fromS2 = dp[j - 1] && s2.charAt(j - 1) == s3.charAt(i + j - 1);
                dp[j] = fromS1 || fromS2;
            }
        }
        return dp[n];
    }
}
